import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:credentials_app/src/credential_store.dart';
import 'package:credentials_app/src/held_credential.dart';
import 'package:credentials_app/src/holder_key.dart';
import 'package:credentials_app/src/issuer_client.dart';
import 'package:credentials_app/src/presentation_request.dart';
import 'package:credentials_app/src/wallet_service.dart';
import 'package:ssi/ssi.dart';

class NoIssuer implements IssuerClient {
  @override
  Future<HeldCredential> issue({required String holderDid, required String credentialType}) => throw UnimplementedError();
}

PresentationRequest ask(String nonce, Map<String, dynamic> credential) => PresentationRequest.fromJson({
  'client_id': 'door-scanner.members.test', 'nonce': nonce, 'dcql_query': {'credentials': [credential]},
});
Map<String, dynamic> claims(List<String> names) => {'id': 'm', 'format': 'ldp_vc', 'claims': [for (final n in names) {'path': ['credentialSubject', n]}]};

WalletService walletWith(Map<String, dynamic> issuance, {bool withKey = true}) {
  final store = CredentialStore()..save(HeldCredential.fromIssuance(issuance));
  if (withKey) store.holderKey = HolderKey.fromSeed(Uint8List.fromList(List.filled(32, 7)));
  return WalletService(issuer: NoIssuer(), store: store, clock: () => DateTime.fromMillisecondsSinceEpoch(1780272000 * 1000, isUtc: true));
}

Future<void> main() async {
  print('== W1 wallet JCS for the same numbers: ${JcsUtil.canonicalize(1e21)}  ${JcsUtil.canonicalize(1e-7)}  ${JcsUtil.canonicalize(1e300)}');

  final points = jsonDecode(File('../probe/issuance-points.json').readAsStringSync()) as Map<String, dynamic>;
  final id = (points['credential'] as Map)['id'] as String;
  final w = walletWith(points);
  File('../probe/presentations-points.json').writeAsStringSync(jsonEncode({
    'member only': await w.createPresentation(id, ask('n-member', claims(['member']))),
    'member + points': await w.createPresentation(id, ask('n-points', claims(['member', 'points']))),
  }));

  final harbour = jsonDecode(File('../probe/issuance.json').readAsStringSync()) as Map<String, dynamic>;
  final hid = (harbour['credential'] as Map)['id'] as String;
  final sets = await walletWith(harbour).createPresentation(hid, ask('n', {
    'id': 'm', 'format': 'ldp_vc',
    'claims': [{'id': 'a', 'path': ['credentialSubject', 'member']}, {'id': 'b', 'path': ['credentialSubject', 'name']}],
